#!/usr/bin/env bash
# =============================================================================
# HERCOSSNUX PQC IP Core - Layer 3A step 7: ML-KEM-768 Decaps sequencer
#
# Completes ML-KEM-768: KeyGen, Encaps and Decaps all verified against ACVP.
#
# THE CONSTANT-TIME FINDING. The functional test passed with a correct
# comparison, so a timing check was added. It exposed a VECTOR COVERAGE GAP:
# every ACVP rejection vector in this subset corrupts the LAST ciphertext
# byte, so the first difference is at index 1087 of 1088. An early exit in the
# comparison therefore saves nothing and no timing measurement can see it.
# Two rejection vectors that differ at byte 0 were added; with those present
# an early exit finishes ~53 us sooner, far outside the ~2.6 us
# rejection-sampling noise. Mutation M1 injects that early exit and is killed
# only because those vectors exist. Details in doc/L3A_DECAPS.md.
#
# Note that total runtime is NOT constant in ML-KEM: SampleNTT uses rejection
# sampling. The testbench bounds the total spread rather than asserting
# equality, which an earlier attempt did incorrectly.
#
# codec_ct gains d=1 for the recovered message, so its signature changes from
# enc=8 dec=8 sig=2bc73d7b136a2e84 to enc=12 dec=12 sig=bebe187d1862e8b6.
# The dsel port widens to two bits; kem_encaps is updated to match and its
# signature is unchanged.
#
# Requires all earlier Layer 3A deliveries.
# Installs into: $HOME/vhdl_repo/IP_Cores/PQC/
# Expected final line:
#   PQC L3A DECAPS PASS vectors=10 rejected=6 sig=0fd9be3d1fda7c7f
# =============================================================================
set -u
(
  set -e
  DEST="$HOME/vhdl_repo/IP_Cores/PQC"
  mkdir -p "$DEST/rtl" "$DEST/verif" "$DEST/doc"
  for f in rtl/kem_keygen.vhd rtl/poly_mem.vhd rtl/byte_mem.vhd \
           verif/tb_encaps.vhd; do
    if [ ! -f "$DEST/$f" ]; then
      echo "MISSING PREREQUISITE: $f"
      exit 1
    fi
  done
  base64 -d > "$DEST/rtl/kem_decaps.vhd" << 'B64EOF'
