  chmod +x "$DEST/verif/mutate_dec.sh"
  cd "$DEST/verif"
  rm -rf work-obj08.cf
  ghdl -a --std=08 ../rtl/keccak_pkg.vhd ../rtl/keccak_f1600.vhd \
       ../rtl/keccak_sponge.vhd ../rtl/ntt_tables_pkg.vhd \
       ../rtl/pqc_round_pkg.vhd ../rtl/pqc_codec_pkg.vhd ../rtl/ntt_unit.vhd \
       ../rtl/sampler_ntt_k.vhd ../rtl/sampler_misc.vhd ../rtl/basemul_k.vhd \
       ../rtl/poly_mem.vhd ../rtl/byte_mem.vhd ../rtl/codec_ct.vhd \
       ../rtl/kem_keygen.vhd ../rtl/kem_keygen_top.vhd \
       ../rtl/kem_encaps.vhd ../rtl/kem_encaps_top.vhd \
       ../rtl/kem_decaps.vhd ../rtl/kem_decaps_top.vhd \
       tb_poly_mem.vhd tb_datapath.vhd tb_codec12.vhd tb_codec_ct.vhd \
       tb_keygen.vhd tb_encaps.vhd tb_decaps.vhd

  echo "--- regression: previously verified blocks ---"
  for TB in tb_poly_mem tb_datapath tb_codec12 tb_codec_ct; do
    ghdl -e --std=08 $TB > /dev/null 2>&1
  done
  ghdl -r --std=08 tb_poly_mem --stop-time=50ms 2>&1 \
    | grep "POLYMEM PASS" | sed 's/.*(report note): //'
  ghdl -r --std=08 tb_datapath --stop-time=300ms 2>&1 \
    | grep "DATAPATH PASS" | sed 's/.*(report note): //'
  ghdl -r --std=08 tb_codec12 --stop-time=200ms 2>&1 \
    | grep "CODEC12 PASS" | sed 's/.*(report note): //'
  ghdl -r --std=08 tb_codec_ct --stop-time=800ms 2>&1 \
    | grep "CODECCT PASS" | sed 's/.*(report note): //'

  echo "--- KeyGen and Encaps still bit-identical ---"
  ghdl -e --std=08 tb_keygen > /dev/null 2>&1
  ghdl -r --std=08 tb_keygen --stop-time=4000ms 2>&1 \
    | grep "KEYGEN PASS" | sed 's/.*(report note): //'
  ghdl -e --std=08 tb_encaps > /dev/null 2>&1
  ghdl -r --std=08 tb_encaps --stop-time=6000ms 2>&1 \
    | grep "ENCAPS PASS" | sed 's/.*(report note): //'

  echo "--- full Decaps against ACVP, with the timing check ---"
  ghdl -e --std=08 tb_decaps > /dev/null 2>&1
  ghdl -r --std=08 tb_decaps --stop-time=30000ms 2>&1 \
    | grep "DECAPS PASS" | sed 's/.*(report note): //'
)
